#!/usr/bin/env bash
# batch_p06b_final.sh — completes P0.6 Batch B: real deployment wiring + commit + deploy.
#
# Your diagnostic settled everything. Three things it revealed:
#
#  1. redis-cache EXISTS, is healthy, is on the `data` network the gateway
#     already joins - and REQUIRES a password. (NOAUTH once REDISCLI_AUTH is
#     cleared; REDISCLI_AUTH is set inside both Redis containers by compose
#     itself, for the healthcheck - which is exactly why my earlier PONG-based
#     conclusion was wrong. F15 now records this as confirmed, not theorised.)
#  2. METRICS_TOKEN is in NEITHER .env NOR docker-compose.yml. Batch A made
#     main() refuse to start without it, so your next
#     `docker compose up -d --build gateway` would have FAILED TO BOOT. A real
#     landmine, recorded as F16. Every test run passed only because the test
#     command itself injected -e METRICS_TOKEN=test-token.
#  3. `stop_grace_period` was never set on the gateway, so compose used its 10s
#     default - SHORTER than our own 25s shutdown budget. A graceful shutdown
#     could have been SIGKILLed mid spool-flush. Fixed here (30s).
#
# Also: docs/reference/schema.sql confirms the kill-switch scope enum is
# `channel_account`, while the Redis key the spec fixes is `ks:channel:{id}`.
# killswitch.js now accepts BOTH spellings in a ks:changes payload, with a test
# proving each takes effect - cheap now, a silent P0.7 integration bug if left.
#
# WHAT THIS SCRIPT DOES, in order, stopping at nothing that needs a decision
# until the two clearly-marked gates at the end:
#   [1] writes 7 files
#   [2] generates a real 32-byte METRICS_TOKEN into .env if absent (never printed)
#   [3] wires docker-compose.yml's gateway service (backup + validate + AUTO-ROLLBACK)
#   [4] runs killswitch tests against the REAL redis-cache with NO env overrides
#       - so a pass proves the production wiring itself, not a test-only shim
#   [5] runs the full suite the same way
#   GATE A (y/N): commit
#   GATE B (y/N): rebuild + restart the gateway, then prove the kill-switch
#                 end-to-end against the LIVE gateway (423 while off, 404 once
#                 restored), with guaranteed cleanup even on interrupt
#
# Both gates are safety confirmations, not questions about requirements.
# Verified locally before sending: 117/117 via the real `npm test`; the compose
# editor exercised against a faithful replica of your gateway block (idempotent,
# forwarder untouched, comments preserved, re-parsed with a real YAML parser).
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -uo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
cd "$REPO_ROOT" || { echo "ERROR: $REPO_ROOT not found" >&2; exit 1; }
DC="docker compose"; $DC version >/dev/null 2>&1 || DC="docker-compose"
COMPOSE_FILE="docker-compose.yml"

echo "=== [1/5] Writing files (base64-embedded, decoded in place) ==="
write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

