## P0.6 — الجاهزية التشغيلية ومفتاح الطوارئ

### الدفعة أ (مُلتزَمة: `be5debe`)

`GET /readyz`، `GET /metrics` محمية بـBearer، رفض الإقلاع بسرّ `METRICS_TOKEN` فارغ (H5)، تسلسل الإيقاف الرشيق الكامل، تسجيل H12 مع إخفاء الهواتف، وثلاثة مقاييس دورة حياة الجلسة مربوطة بنقاط انتقال حقيقية. 106/106 على الـVPS بعد حل ثلاث مشاكل حقيقية في مُشغّل الاختبارات (F10).

### الدفعة ب — مفتاح الطوارئ على جانب البوابة

`gateway/src/killswitch.js`: اتصالا `redis-cache` (أوامر + مشترك pub/sub منفصلان)، ذاكرة نطاقات داخلية، حساب «الأشد فوزاً» عبر (global × tenant × channel) × (القدرة، `*`) — مطابق حرفياً لدلالة `app.effective_switch` في `docs/reference/schema.sql`، مزامنة كاملة كل 30 ثانية، وقاعدة التقادم (`KS_STALE_MAX_S=120`) التي تُغلق marketing/broadcast فقط. الحجب: `423` بجسم `{error:'blocked_by_switch', capability, state, scope}` عند الطلب، و`failed(error_class='blocked')` للعناصر التي كانت في الطابور.

**11/11 اختباراً حقيقياً** ضد `redis-cache` حقيقي: مصفوفة النطاقات/الحالات، القدرة `*`، تعيين `kind`←القدرات، زمن الانتشار من `PUBLISH` إلى الحجب **مُقاس فعلياً < 1 ثانية**، سلوك التقادم بزمن حقيقي، وقبول صيغتي النطاق (`channel` و`channel_account`).

**أربعة عيوب حقيقية اكتُشفت وأُصلحت أثناء البناء، كلها موثَّقة بأرقام مقيسة:**
- **F11** — أوامر Redis قبل انتظار `'ready'` (`enableOfflineQueue:false`).
- **F13** — مفتاح القتل كان **تبعية إقلاع**: جاهزية البوابة 1057ms ← 10698ms، والإيقاف 13ms ← 8475ms عندما يكون `redis-cache` مفتوحاً على TCP بلا إجابة. بعد الإصلاح: 2157ms و1014ms، بسقوف مكتوبة (H4). الإيقاف كان سيضرب `SHUTDOWN_TIMEOUT_MS=5000` ويخرج برمز 1.
- **F16** — `METRICS_TOKEN` مفقود من `.env` و`docker-compose.yml`: أول نشر بعد الدفعة أ كان سيمنع البوابة من الإقلاع كلياً.
- **F14** — فشل عابر في `outbound_chaos.test.js` (تنافس معالج، غير قابل للتكرار محلياً) كشف عيبين في أداة الاختبار: عمى تشخيصي وتعليق عند الفشل — أُصلحا (الفشل الآن يحمل مخرجات الطفل ويُبلِغ في ~6 ثوانٍ بدل التعليق).

**وتصحيح استنتاج خاطئ سجّلتُه أنا أولاً:** ادّعيتُ أن `docker-compose.yml` لا يملك خدمة `redis-cache`، استناداً إلى `ECONNREFUSED` وهي رسالة لا تحمل تلك المعلومة. الواقع: الخدمة موجودة وصحّية منذ أيام، والناقص كان المتغيّر وحده. التصحيح الكامل في D-26 وF15.

### ما تبقّى من P0.6

المراقبة: ربط عائلات المقاييس المتبقّية (`ingest_*`، `out_*`، `forwarder_*`، `dlq_length`، `stream_*`، `media_*`)، نقطة `/metrics` لحاوية الـforwarder، ثم `ops/prometheus/prometheus.yml` و`alerts.yml` بالقواعد الثماني، والتحقق بـ`promtool check rules`. سبب عدم تسليمها مع الدفعة ب مسجَّل في D-27.
P06PROGRESSEOF
  echo "  appended the P0.6 section ($(wc -c < docs/P0_PROGRESS.md) bytes total now); a .bak was written first."
fi

echo ""
echo "=== [2/5] METRICS_TOKEN in .env (required since Batch A - see F16) ==="
if [ ! -f .env ]; then
  echo "  ERROR: no .env in $REPO_ROOT - cannot continue safely." >&2; exit 1
fi
if grep -qE '^METRICS_TOKEN=.+' .env; then
  echo "  .env already defines a non-empty METRICS_TOKEN - left untouched."
else
  cp .env ".env.bak.$(date -u +%Y%m%dT%H%M%SZ)"
  {
    printf '\n# P0.6 (H5): REQUIRED - gateway/src/index.js main() refuses to start with an\n'
    printf '# empty value. Generated %s by batch_p06b_final.sh.\n' "$(date -u +%FT%TZ)"
    printf 'METRICS_TOKEN=%s\n' "$(node -e "console.log(require('crypto').randomBytes(32).toString('base64url'))")"
  } >> .env
  echo "  generated a random 32-byte METRICS_TOKEN and appended it to .env (value NOT printed)."
  echo "  a timestamped .env backup was written alongside it."
fi

echo ""
echo "=== [3/5] Wiring docker-compose.yml's gateway service ==="
PRE_HASH="$(md5sum "$COMPOSE_FILE" | awk '{print $1}')"
node ops/wire_p06.mjs "$COMPOSE_FILE"; WIRE_RC=$?
POST_HASH="$(md5sum "$COMPOSE_FILE" | awk '{print $1}')"
BAK="$(ls -t "$COMPOSE_FILE".bak.* 2>/dev/null | head -1)"

if [ "$WIRE_RC" -ne 0 ]; then
  echo "  The editor REFUSED (see above). Nothing was written to compose." >&2
  exit 1
fi
if [ "$PRE_HASH" != "$POST_HASH" ]; then
  echo ""
  echo "--- exact diff applied ---"
  [ -n "$BAK" ] && diff -u "$BAK" "$COMPOSE_FILE" | sed 's/^/  /'
  echo ""
  echo "--- validating with docker compose config ---"
  if timeout -k 10 --foreground 120 $DC config -q; then
    echo "  compose VALIDATES"
  else
    echo "  compose config FAILED - RESTORING BACKUP" >&2
    [ -n "$BAK" ] && cp "$BAK" "$COMPOSE_FILE" && echo "  restored from $BAK" >&2
    exit 1
  fi
else
  echo "  (already wired; nothing changed)"
fi
echo "--- confirming the gateway now resolves REDIS_CACHE_HOST + METRICS_TOKEN (names only) ---"
timeout -k 10 --foreground 120 $DC config 2>/dev/null \
  | grep -oE 'REDIS_CACHE_(HOST|PORT)|METRICS_TOKEN|NODE_OPTIONS|stop_grace_period' | sort -u | sed 's/^/  resolved: /'

# --------------------------------------------------------------------------
# Tests with NO REDIS_CACHE_* / METRICS_TOKEN overrides: they now come from
# compose + .env, so a pass proves the real wiring. -T + </dev/null + hard
# SIGKILL backstop so nothing can hang.
# --------------------------------------------------------------------------
MOUNTS=(-v "$(pwd)/gateway/src:/app/src:ro" -v "$(pwd)/gateway/scripts:/app/scripts:ro" -v "$(pwd)/gateway/test-support:/app/test-support:ro" -v "$(pwd)/gateway/package.json:/app/package.json:ro")
TEST_ENV=(-e ALLOW_FAKE_WA=1 -e NODE_ENV=test -e LOG_LEVEL=error)
KS_STATUS="not run"; FULL_STATUS="not run"

echo ""
echo "=== [4/5] killswitch.test.js against the REAL redis-cache (no overrides) ==="
timeout -k 30 --foreground 300 $DC run --rm -T "${TEST_ENV[@]}" "${MOUNTS[@]}" gateway \
  node --test src/__tests__/killswitch.test.js </dev/null
if [ $? -eq 0 ]; then KS_STATUS="PASS"; else KS_STATUS="FAIL/TIMEOUT"; fi
echo "  -> killswitch.test.js: $KS_STATUS"

echo ""
echo "=== [5/5] Full suite (npm test), same real wiring ==="
timeout -k 30 --foreground 700 $DC run --rm -T "${TEST_ENV[@]}" "${MOUNTS[@]}" gateway npm test </dev/null
if [ $? -eq 0 ]; then FULL_STATUS="PASS"; else FULL_STATUS="FAIL/TIMEOUT"; fi

echo ""
echo "============================ RESULTS ============================"
echo "  killswitch.test.js (real redis-cache) : $KS_STATUS"
echo "  full suite (npm test)                 : $FULL_STATUS"
echo "================================================================="

if [ "$KS_STATUS" != "PASS" ] || [ "$FULL_STATUS" != "PASS" ]; then
  echo ""
  echo "Tests did not all pass - stopping here. Nothing committed, nothing deployed."
  echo "The compose wiring and .env token ARE in place (both idempotent, safe to re-run)."
  echo "Paste the output above and I will fix the actual failure."
  exit 1
fi

# ----------------------------- GATE A: commit -----------------------------
P06B_PATHS=(
  gateway/src/killswitch.js
  gateway/src/__tests__/killswitch.test.js
  gateway/src/config.js
  gateway/src/index.js
  gateway/src/metrics.js
  gateway/src/sessions.js
  gateway/src/outbound/queue.js
  gateway/src/__tests__/outbound_chaos.test.js
  gateway/.env.example
  ops/wire_p06.mjs
  docker-compose.yml
  docs/P0_DEVIATIONS.md
  docs/P0_FINDINGS.md
  docs/P0_PROGRESS.md
  docs/PHASE_GATE.md
)
echo ""
echo "=== GATE A: commit P0.6 Batch B ==="
for p in "${P06B_PATHS[@]}"; do
  [ -e "$p" ] || { echo "  ERROR: expected path missing: $p" >&2; exit 1; }
done
git add -- "${P06B_PATHS[@]}"
echo "--- git diff --cached --stat ---"
git diff --cached --stat
echo ""
echo "--- left alone (not part of this commit) ---"
git status --short | grep -vE '^[AMD] ' | head -8
echo "  ... (batch_p0*.sh scratch scripts and *_run.log files, as in every prior commit)"
echo ""
read -p "Create this commit? [y/N] " -n 1 -r; echo ""
if [[ $REPLY =~ ^[Yy]$ ]]; then
  git commit -m "$(cat <<'COMMITMSG'
P0.6 Batch B: gateway-side kill-switch + real deployment wiring

gateway/src/killswitch.js (new): the enforcement half of the kill-switch.
Two dedicated redis-cache connections (one command, one pub/sub subscriber -
ioredis multiplexes commands over a single connection and a subscribing client
cannot issue others, the F8 lesson). In-memory scope cache; strictest-wins
effective state across (global, tenant, channel) x (capability, '*'), matching
docs/reference/schema.sql's app.effective_switch semantics literally
(off > degraded > on). Full resync every 30s; ks:changes pub/sub triggers a
targeted HGETALL rather than trusting a state payload, so the hash stays the
only source of truth. Staleness past KS_STALE_MAX_S (120s) fails marketing and
broadcast closed while every other capability keeps its last-known value.
Accepts BOTH 'channel' and the DB enum's 'channel_account' in a ks:changes
payload, each covered by a test.

outbound/queue.js: the P0.4-era always-allow stub is replaced by a real check
injected through ctx (same convention as getSocket, so queue.js needs no
import of killswitch.js and every existing test's bare ctx keeps working).
A blocked item now becomes failed(error_class='blocked') with capability/state/
scope on the evt stream and an out_blocked_total{capability} increment - NOT
requeued forever, per the spec's own wording.

index.js: POST /sessions/:id/send returns 423 {error:'blocked_by_switch',
capability, state, scope} at request time; killswitch start/stop wired into
main()/shutdown(). sessions.js: nullable tenantId/channelAccountId plumbing
(always null today - no caller sets them and no session->tenant mapping exists
until P0.7; killswitch.js resolves that through the spec's own documented
global-only fallback). metrics.js: killswitch_state{scope,capability},
killswitch_stale_seconds, out_blocked_total{capability}.

Two real, MEASURED defects found and fixed during this batch (F13): the
kill-switch was a startup dependency - a redis-cache reachable at TCP level but
never answering pushed gateway readiness from 1057ms to 10698ms and graceful
shutdown from 13ms to 8475ms (which would have blown p06's own 5000ms budget
and exited 1). start() now arms its retry timers before any await and races the
initial sync against a 1500ms cap, finishing in the background if it overruns;
stop() closes both clients in parallel, each capped at 1000ms, then disconnects
locally. After: 2157ms / 1014ms, exit 0. Confirmed on the VPS, where p06's
graceful-shutdown test passed while killswitch pointed at an unusable Redis.

Deployment wiring (D-27, and F16 for the landmine): docker-compose.yml's
gateway service gains REDIS_CACHE_HOST/PORT/PASSWORD (redis-cache exists, is
healthy, and requires a password - my earlier claim that no such service
existed was wrong, corrected in D-26), METRICS_TOKEN (without which main() has
refused to start since Batch A - the next deploy would have failed to boot),
NODE_OPTIONS=--max-old-space-size=900, mem_limit/memswap_limit 512m->1200m, and
stop_grace_period: 30s (compose's 10s default was SHORTER than our own 25s
shutdown budget, so a correct graceful shutdown could have been SIGKILLed
mid-flush). gateway-forwarder deliberately unchanged: it runs forwarder.js, not
main(), so it has no kill-switch and no token requirement - the asymmetry D-21
was designed for. Applied by ops/wire_p06.mjs, a surgical idempotent editor
with backup and rollback, rather than a YAML round-trip that would strip every
comment from real infrastructure.

outbound_chaos.test.js (F14): its earlier VPS failure was transient CPU
contention, not a regression - the chaos child never builds a kill-switch at
all. But it was undiagnosable and it HUNG, so the child's stdout/stderr is now
attached to every timing assertion and a t.after hook kills the child whether
the test passes or fails. No timeout budget was touched.

Monitoring (Prometheus + alert rules) is deliberately NOT in this commit: the
spec's eight rules depend on metric families not yet wired and on a forwarder
/metrics endpoint that does not exist, and a rule over a missing metric reads
as a confirmed zero - exactly what D-22 forbids. It lands complete in the next
and final P0.6 batch (D-27 records this).

Verified: 117/117 via the real `npm test` locally, then again on the VPS
against the real redis-cache with NO env overrides, so the production wiring
itself is what the tests exercised.

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01CkxAKMfgEw8DfNPpm6i7b3
COMMITMSG
)" && echo "" && git log -1 --stat | head -30
else
  echo "  Skipped. Files stay staged; 'git reset' unstages them."
fi

# ------------------- GATE B: deploy + live end-to-end proof -------------------
echo ""
echo "=== GATE B: rebuild + restart the gateway, then prove the kill-switch live ==="
echo "  This rebuilds the gateway image with the new code and restarts the container"
echo "  (graceful shutdown is exactly what P0.5/P0.6 built and tested). It then:"
echo "    - checks /healthz and /readyz,"
echo "    - checks /metrics rejects no-token and accepts the real token,"
echo "    - briefly sets ks:global ai_reply=off in the REAL redis-cache, PUBLISHes,"
echo "      and asserts POST /sessions/<probe>/send returns 423, then RESTORES it"
echo "      and asserts the block is gone. Cleanup is trapped, so it runs even on"
echo "      Ctrl+C or any error."
echo "  NOTE: that flip briefly disables bot replies (a few seconds) on the live"
echo "  gateway. Say no if now is a bad moment - everything above is already done."
echo ""
read -p "Rebuild, restart and verify live? [y/N] " -n 1 -r; echo ""
if [[ ! $REPLY =~ ^[Yy]$ ]]; then
  echo "  Skipped. The wiring is in place; deploy later with:"
  echo "      docker compose up -d --build gateway"
  exit 0
fi

# read secrets without ever printing them
RC_PASS="$(grep -E '^REDIS_CACHE_PASSWORD=' .env | head -1 | cut -d= -f2-)"
MT="$(grep -E '^METRICS_TOKEN=' .env | head -1 | cut -d= -f2-)"
AK="$(grep -E '^SHARWA_AI_GATEWAY_API_KEY=' .env | head -1 | cut -d= -f2-)"

restore_switch() {
  docker exec -e REDISCLI_AUTH="$RC_PASS" sharwa_ai-redis-cache-1 \
    redis-cli HDEL ks:global ai_reply >/dev/null 2>&1
  docker exec -e REDISCLI_AUTH="$RC_PASS" sharwa_ai-redis-cache-1 \
    redis-cli PUBLISH ks:changes '{"scope":"global"}' >/dev/null 2>&1
  echo "  [cleanup] ks:global ai_reply removed and change published."
}
trap restore_switch EXIT INT TERM

echo ""
echo "--- rebuilding + restarting gateway ---"
timeout -k 60 --foreground 600 $DC up -d --build gateway </dev/null || { echo "  build/restart FAILED" >&2; exit 1; }

echo "--- waiting for /healthz ---"
UP=no
for i in $(seq 1 60); do
  if curl -fsS -o /dev/null http://127.0.0.1:4001/healthz 2>/dev/null; then UP=yes; break; fi
  sleep 1
done
echo "  /healthz reachable: $UP"
if [ "$UP" != "yes" ]; then
  echo "  gateway did not come up. Recent logs:" >&2
  $DC logs --tail 40 gateway
  exit 1
fi

echo "--- /readyz ---"
curl -sS -o /tmp/readyz.out -w '  HTTP %{http_code}\n' http://127.0.0.1:4001/readyz; head -c 200 /tmp/readyz.out; echo ""
echo "--- /metrics without a token (expect 401) ---"
curl -sS -o /dev/null -w '  HTTP %{http_code}\n' http://127.0.0.1:4001/metrics
echo "--- /metrics with the real token (expect 200 + killswitch metrics present) ---"
curl -sS -H "Authorization: Bearer $MT" http://127.0.0.1:4001/metrics \
  | grep -E '^# HELP (killswitch_stale_seconds|killswitch_state|out_blocked_total|session_state|process_resident_memory_bytes)' \
  | sed 's/^/  /' || echo "  (expected metric HELP lines not found)"

echo ""
echo "--- LIVE kill-switch proof: flipping global ai_reply=off ---"
docker exec -e REDISCLI_AUTH="$RC_PASS" sharwa_ai-redis-cache-1 redis-cli HSET ks:global ai_reply off >/dev/null
docker exec -e REDISCLI_AUTH="$RC_PASS" sharwa_ai-redis-cache-1 redis-cli PUBLISH ks:changes '{"scope":"global"}' >/dev/null
sleep 1
CODE_OFF="$(curl -sS -o /tmp/ks.out -w '%{http_code}' -X POST \
  -H "X-API-Key: $AK" -H 'Content-Type: application/json' \
  -d '{"to":"0@s.whatsapp.net","text":"kill-switch probe"}' \
  http://127.0.0.1:4001/sessions/ks-probe-nonexistent/send)"
echo "  POST /send while OFF -> HTTP $CODE_OFF (expect 423)"
echo "  body: $(head -c 200 /tmp/ks.out)"

restore_switch
trap - EXIT INT TERM
sleep 1
CODE_ON="$(curl -sS -o /dev/null -w '%{http_code}' -X POST \
  -H "X-API-Key: $AK" -H 'Content-Type: application/json' \
  -d '{"to":"0@s.whatsapp.net","text":"kill-switch probe"}' \
  http://127.0.0.1:4001/sessions/ks-probe-nonexistent/send)"
echo "  POST /send after RESTORE -> HTTP $CODE_ON (expect 404: the probe session does not exist,"
echo "  which proves the request got PAST the kill-switch check this time)"

echo ""
echo "--- confirming the switch really is restored in redis-cache (expect empty) ---"
docker exec -e REDISCLI_AUTH="$RC_PASS" sharwa_ai-redis-cache-1 redis-cli HGETALL ks:global | sed 's/^/  /'
echo "  (empty output above = no global restriction left in place)"

echo ""
echo "=========================== SUMMARY ==========================="
echo "  tests                 : killswitch $KS_STATUS / full suite $FULL_STATUS"
echo "  live /send while OFF  : HTTP $CODE_OFF  (423 = kill-switch enforced)"
echo "  live /send restored   : HTTP $CODE_ON   (404 = passed the check)"
echo "==============================================================="
echo ""
echo "If 423 then 404 appeared above, P0.6 Batch B is proven end to end on real"
echo "infrastructure. The one remaining piece of P0.6 is monitoring, which I will"
echo "deliver next: the remaining metric families, a /metrics endpoint for the"
echo "forwarder container, ops/prometheus/prometheus.yml + alerts.yml with the"
echo "spec's eight rules, promtool validation, and the prometheus service."
